INSERT INTO shj_text_sections(id,edition_id,parent_id,slug,sequence,reference_label,title_zh,title_en,summary_zh,summary_en,review_status) VALUES
('12000000-0000-4000-8000-000000000002','11000000-0000-4000-8000-000000000001',NULL,'nanci2-route',2,'南山经·南次二经','南山经·南次二经','Nanshan Jing · Second Southern Route','自柜山东行至漆吴之山的十七山序列；其神龙身鸟首。','Seventeen mountains from Mount Ju east to Mount Qiwu; their spirits are dragon-bodied and bird-headed.','published'),
('12000000-0000-4000-8000-000000000003','11000000-0000-4000-8000-000000000001',NULL,'nanci3-route',3,'南山经·南次三经','南山经·南次三经','Nanshan Jing · Third Southern Route','自天虞之山至南禺之山的山列；其神龙身人面。','The route from Mount Tianyu to Mount Nanyu; their spirits are dragon-bodied and human-faced.','published')
INSERT INTO shj_text_passages(id,section_id,slug,reference_key,sequence,text_zh,normalized_text_zh,source_url,checksum_sha256,review_status) VALUES
('13000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000001','zhaoyao','南山经·招摇之山',1,'南山經之首曰䧿山。其首曰招搖之山，臨于西海之上，多桂，多金玉。有草焉，其狀如韭而青花，其名曰祝餘，食之不飢。有木焉，其狀如穀而黑理，其花四照，其名曰迷穀，佩之不迷。有獸焉，其狀如禺而白耳，伏行人走，其名曰狌狌，食之善走。麗𪊨之水出焉，而西流注于海，其中多育沛，佩之無瘕疾。','南山經之首曰䧿山。其首曰招搖之山，臨于西海之上，多桂，多金玉。有草焉，其狀如韭而青花，其名曰祝餘，食之不飢。有木焉，其狀如穀而黑理，其花四照，其名曰迷穀，佩之不迷。有獸焉，其狀如禺而白耳，伏行人走，其名曰狌狌，食之善走。麗𪊨之水出焉，而西流注于海，其中多育沛，佩之無瘕疾。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','5dada3a1e3e2184818c72effdde4b34c56be517f1fe78a1bffecf697c701759b','published'),
('13000000-0000-4000-8000-000000000002','12000000-0000-4000-8000-000000000001','tangting','南山经·堂庭之山',2,'又東三百里，曰堂庭之山，多棪木，多白猿，多水玉，多黃金。','又東三百里，曰堂庭之山，多棪木，多白猿，多水玉，多黃金。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','4e278da88b10cfa5bbe8cce6a86170582a1dca1462ff0f717e2ee7397afbdcfc','published'),
('13000000-0000-4000-8000-000000000003','12000000-0000-4000-8000-000000000001','yuanyi','南山经·猨翼之山',3,'又東三百八十里，曰猨翼之山，其中多怪獸，水多怪魚，多白玉，多蝮虫，多怪蛇，多怪木，不可以上。','又東三百八十里，曰猨翼之山，其中多怪獸，水多怪魚，多白玉，多蝮虫，多怪蛇，多怪木，不可以上。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','8ff7a8946e38004a4880fb9201274d33312fad027ad6f4c7707e3f3eb36441b1','published'),
('13000000-0000-4000-8000-000000000004','12000000-0000-4000-8000-000000000001','niuyang','南山经·杻阳之山',4,'又東三百七十里，曰杻陽之山，其陽多赤金，其陰多白金。有獸焉，其狀如馬而白首，其文如虎而赤尾，其音如謠，其名曰鹿蜀，佩之宜子孫。怪水出焉，而東流注于憲翼之水。其中多玄龜，其狀如龜而鳥首虺尾，其名曰旋龜，其音如判木，佩之不聾，可以為底。','又東三百七十里，曰杻陽之山，其陽多赤金，其陰多白金。有獸焉，其狀如馬而白首，其文如虎而赤尾，其音如謠，其名曰鹿蜀，佩之宜子孫。怪水出焉，而東流注于憲翼之水。其中多玄龜，其狀如龜而鳥首虺尾，其名曰旋龜，其音如判木，佩之不聾，可以為底。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','60e917191611bc7711d521e8cb7f5ef754fafaf61152c430716dd9be72d6bef9','published'),
('13000000-0000-4000-8000-000000000005','12000000-0000-4000-8000-000000000001','dishan','南山经·柢山',5,'又東三百里，曰柢山，多水，無草木。有魚焉，其狀如牛，陵居，蛇尾有翼，其羽在魼下，其音如留牛，其名曰鯥，冬死而夏生，食之無腫疾。','又東三百里，曰柢山，多水，無草木。有魚焉，其狀如牛，陵居，蛇尾有翼，其羽在魼下，其音如留牛，其名曰鯥，冬死而夏生，食之無腫疾。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','76f7c8c251ad2270259e55f93323f7d90c85e2082565294fa09008a960cb97dd','published'),
('13000000-0000-4000-8000-000000000006','12000000-0000-4000-8000-000000000001','danyuan','南山经·亶爰之山',6,'又東四百里，曰亶爰之山，多水，無草木，不可以上。有獸焉，其狀如狸而有髦，其名曰類，自為牝牡，食者不妬。','又東四百里，曰亶爰之山，多水，無草木，不可以上。有獸焉，其狀如狸而有髦，其名曰類，自為牝牡，食者不妬。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','02c2129bb2e67a0ed5c14a9e0badcc7561ff19bf195a5cedc02543aa41881431','published'),
('13000000-0000-4000-8000-000000000007','12000000-0000-4000-8000-000000000001','jishan','南山经·基山',7,'又東三百里，曰基山，其陽多玉，其陰多怪木。有獸焉，其狀如羊，九尾四耳，其目在背，其名曰猼訑，佩之不畏。有鳥焉，其狀如雞而三首六目，六足三翼，其名曰𪁺𩿧，食之無臥。','又東三百里，曰基山，其陽多玉，其陰多怪木。有獸焉，其狀如羊，九尾四耳，其目在背，其名曰猼訑，佩之不畏。有鳥焉，其狀如雞而三首六目，六足三翼，其名曰𪁺𩿧，食之無臥。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','e4cbb1fec19e86e777e5285daabf7d3df60876edfbb212d46e1ccfff84e5e245','published'),
('13000000-0000-4000-8000-000000000008','12000000-0000-4000-8000-000000000001','qingqiu','南山经·青丘之山',8,'又東三百里，曰青丘之山，其陽多玉，其陰多青䨼。有獸焉，其狀如狐而九尾，其音如嬰兒，能食人，食者不蠱。有鳥焉，其狀如鳩，其音若呵，名曰灌灌，佩之不惑。英水出焉，南流注于即翼之澤。其中多赤鱬，其狀如魚而人面，其音如鴛鴦，食之不疥。','又東三百里，曰青丘之山，其陽多玉，其陰多青䨼。有獸焉，其狀如狐而九尾，其音如嬰兒，能食人，食者不蠱。有鳥焉，其狀如鳩，其音若呵，名曰灌灌，佩之不惑。英水出焉，南流注于即翼之澤。其中多赤鱬，其狀如魚而人面，其音如鴛鴦，食之不疥。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','68cdb5e582e6a71f80f3bc42ea4dccd463728c05adafee8a9b617cf9049a7ced','published'),
('13000000-0000-4000-8000-000000000009','12000000-0000-4000-8000-000000000001','jiwei','南山经·箕尾之山',9,'又東三百五十里，曰箕尾之山，其尾踆于東海，多沙石。汸水出焉，而南流注于淯，其中多白玉。','又東三百五十里，曰箕尾之山，其尾踆于東海，多沙石。汸水出焉，而南流注于淯，其中多白玉。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','71b10ce46e42cd59355788e5e636ee56872c5c84453391c8fbce73e93bce260c','published'),
('13000000-0000-4000-8000-000000000010','12000000-0000-4000-8000-000000000001','queshan-summary','南山经·鹊山首列·祠礼',10,'凡䧿山之首，自招搖之山，以至箕尾之山，凡十山，二千九百五十里。其神狀皆鳥身而龍首，其祠之禮：毛用一璋玉瘞，糈用稌米，一壁，稻米、白菅為席。','凡䧿山之首，自招搖之山，以至箕尾之山，凡十山，二千九百五十里。其神狀皆鳥身而龍首，其祠之禮：毛用一璋玉瘞，糈用稌米，一壁，稻米、白菅為席。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','9bcb67a25cb15fc5863325cbbea1ba55de99bb6acb9cf74c94bff783e490f697','published'),
('13000000-0000-4000-8000-000000000011','12000000-0000-4000-8000-000000000002','jushan','南山经·柜山',1,'《南次二經》之首，曰柜山，西臨流黃，北望諸毗，東望長右。英水出焉，西南流注于赤水，其中多白玉，多丹粟。有獸焉，其狀如豚，有距，其音如狗吠，其名曰狸力，見則其縣多土功。有鳥焉，其狀如鴟而人手，其音如痺，其名曰鴸，其鳴自號也，見則其縣多放士。','《南次二經》之首，曰柜山，西臨流黃，北望諸毗，東望長右。英水出焉，西南流注于赤水，其中多白玉，多丹粟。有獸焉，其狀如豚，有距，其音如狗吠，其名曰狸力，見則其縣多土功。有鳥焉，其狀如鴟而人手，其音如痺，其名曰鴸，其鳴自號也，見則其縣多放士。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','e661e85d44d219b6ca64b44bb2c5b2f97d80b3f02791e94da1533d7e49b4b8f1','published'),
('13000000-0000-4000-8000-000000000012','12000000-0000-4000-8000-000000000002','changyou','南山经·长右之山',2,'東南四百五十里，曰長右之山，無草木，多水。有獸焉，其狀如禺而四耳，其名長右，其音如吟，見則郡縣大水。','東南四百五十里，曰長右之山，無草木，多水。有獸焉，其狀如禺而四耳，其名長右，其音如吟，見則郡縣大水。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','4a259fc7a3fe19236fb6dc339857d9ea1b6929ca94d516304bf6d9a967c5f37f','published'),
('13000000-0000-4000-8000-000000000013','12000000-0000-4000-8000-000000000002','yaoguang','南山经·尧光之山',3,'又東三百四十里曰堯光之山，其陽多玉，其陰多金。有獸焉，其狀如人而彘鬣，穴居而冬蟄，其名曰猾褢，其音如斲木，見則縣有大繇。','又東三百四十里曰堯光之山，其陽多玉，其陰多金。有獸焉，其狀如人而彘鬣，穴居而冬蟄，其名曰猾褢，其音如斲木，見則縣有大繇。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','cc9f7d1a4a69b52c179198dd28fa9b8aa3787bf3e50c6ec1f21e8bd1c56c1d78','published'),
('13000000-0000-4000-8000-000000000014','12000000-0000-4000-8000-000000000002','yushan','南山经·羽山',4,'又東三百五十里，曰羽山，其下多水，其上多雨，無草木，多蝮虫。','又東三百五十里，曰羽山，其下多水，其上多雨，無草木，多蝮虫。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','01e5b4796c764cdaa134f719a5b098edcb416b2d3971101379af7b5ef5cc4a0f','published'),
('13000000-0000-4000-8000-000000000015','12000000-0000-4000-8000-000000000002','qufu','南山经·瞿父之山',5,'又東三百七十里，曰瞿父之山，無草木，多金玉。','又東三百七十里，曰瞿父之山，無草木，多金玉。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','dbc10e2aac282df4e395527ce3f4d216221687860c7febc60456461feef3ed16','published'),
('13000000-0000-4000-8000-000000000016','12000000-0000-4000-8000-000000000002','juyu','南山经·句馀之山',6,'又東四百里，曰句餘之山，無草木，多金玉。','又東四百里，曰句餘之山，無草木，多金玉。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','56ce7d2edb525eed377cebdb91b999b0c0677028c811e074de882d83448bb92a','published'),
('13000000-0000-4000-8000-000000000017','12000000-0000-4000-8000-000000000002','fuyu','南山经·浮玉之山',7,'又東五百里，曰浮玉之山，北望具區，東望諸毗。有獸焉，其狀如虎而牛尾，其音如吠犬，其名曰彘，是食人。苕水出于其陰，北流注于具區。其中多鮆魚。','又東五百里，曰浮玉之山，北望具區，東望諸毗。有獸焉，其狀如虎而牛尾，其音如吠犬，其名曰彘，是食人。苕水出于其陰，北流注于具區。其中多鮆魚。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','241687be93fd53f4471843c15fb16852f707bf6dc55fcec22a61e468c3201313','published'),
('13000000-0000-4000-8000-000000000018','12000000-0000-4000-8000-000000000002','chengshan','南山经·成山',8,'又東五百里，曰成山，四方而三壇，其上多金玉，其下多青䨼。𨴯水出焉，而南流注于虖勺，其中多黃金。','又東五百里，曰成山，四方而三壇，其上多金玉，其下多青䨼。𨴯水出焉，而南流注于虖勺，其中多黃金。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','aaf6d61291a57dbf96ad9349267a52dd0391e6495b8b743ca1937f7f5349779e','published'),
('13000000-0000-4000-8000-000000000019','12000000-0000-4000-8000-000000000002','kuaiji','南山经·会稽之山',9,'又東五百里，曰會稽之山，四方，其上多金玉，其下多砆石。勺水出焉，而南流注于湨。','又東五百里，曰會稽之山，四方，其上多金玉，其下多砆石。勺水出焉，而南流注于湨。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','9f06d6775704cbe18481430fb7135392a3f8686d468d7083b23d2ef900f005d2','published'),
('13000000-0000-4000-8000-000000000020','12000000-0000-4000-8000-000000000002','yishan','南山经·夷山',10,'又東五百里，曰夷山，無草木，多沙石，湨水出焉，而南流注于列塗。','又東五百里，曰夷山，無草木，多沙石，湨水出焉，而南流注于列塗。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','f7c2ac1b721fd43b4d985e496714fbc44ac05ba79d07d95ca4831221c0706a05','published'),
('13000000-0000-4000-8000-000000000021','12000000-0000-4000-8000-000000000002','pugou','南山经·仆勾之山',11,'又東五百里，曰僕勾之山，其上多金玉，其下多草木，無鳥獸，無水。','又東五百里，曰僕勾之山，其上多金玉，其下多草木，無鳥獸，無水。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','757d7436a675e601316ccbb56a382507073218c5008dec8de0951a6e076d1f2f','published'),
('13000000-0000-4000-8000-000000000022','12000000-0000-4000-8000-000000000002','xianyin','南山经·咸阴之山',12,'又東五百里，曰咸陰之山，無草木，無水。','又東五百里，曰咸陰之山，無草木，無水。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','fb18b2945151d1e87ef2eab13b4845bae71977b239279a811414af5ab8630e3d','published'),
('13000000-0000-4000-8000-000000000023','12000000-0000-4000-8000-000000000002','xunshan','南山经·洵山',13,'又東四百里，曰洵山，其陽多金，其陰多玉。有獸焉，其狀如羊而無口，不可殺也，其名曰䍺。洵水出焉，而南流注于閼之澤，其中多芘蠃。','又東四百里，曰洵山，其陽多金，其陰多玉。有獸焉，其狀如羊而無口，不可殺也，其名曰䍺。洵水出焉，而南流注于閼之澤，其中多芘蠃。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','273d61d5b2b8ba817d64cd90d12d514153abbf0850b07ed444d3ab4bddbe5152','published'),
('13000000-0000-4000-8000-000000000024','12000000-0000-4000-8000-000000000002','hushao','南山经·虖勺之山',14,'又東四百里，曰虖勺之山，其上多梓柟，其下多荊杞。滂水出焉，而東流注于海。','又東四百里，曰虖勺之山，其上多梓柟，其下多荊杞。滂水出焉，而東流注于海。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','a93ad200ca06abe209949fa5994bad845f102f590bcfe17f2c023eb2f9129ab8','published'),
('13000000-0000-4000-8000-000000000025','12000000-0000-4000-8000-000000000002','quwu','南山经·区吴之山',15,'又東五百里，曰區吳之山，無草木，多砂石。鹿水出焉，而南流注于滂水。','又東五百里，曰區吳之山，無草木，多砂石。鹿水出焉，而南流注于滂水。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','f29971ac16ecb4fd191450e64db7ae88892e010927acc8f8ed7819e098052fa3','published'),
('13000000-0000-4000-8000-000000000026','12000000-0000-4000-8000-000000000002','luwu','南山经·鹿吴之山',16,'又東五百里，曰鹿吳之山，上無草木，多金石。澤更之水出焉，而南流注于滂水。水有獸焉，名曰蠱雕，其狀如雕而有角，其音如嬰兒之音，是食人。','又東五百里，曰鹿吳之山，上無草木，多金石。澤更之水出焉，而南流注于滂水。水有獸焉，名曰蠱雕，其狀如雕而有角，其音如嬰兒之音，是食人。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','4d5e85bb931452d088c03f2e15aa60011592aa235c7d054ad7756f826e967732','published'),
('13000000-0000-4000-8000-000000000027','12000000-0000-4000-8000-000000000002','qiwu','南山经·漆吴之山',17,'東五百里，曰漆吳之山，無草木，多博石，無玉。處于海，東望丘山，其光載出載入，是惟日次。','東五百里，曰漆吳之山，無草木，多博石，無玉。處于海，東望丘山，其光載出載入，是惟日次。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','6060986a8974880728005332802ccc272445ef845f1cae8bfe9537abebcd034b','published'),
('13000000-0000-4000-8000-000000000028','12000000-0000-4000-8000-000000000002','nanci2-summary','南山经·南次二经·祠礼',18,'凡《南次二經》之首，自柜山至于漆吳之山，凡十七山，七千二百里。其神狀皆龍身而鳥首。其祠：毛用一璧瘞，糈用稌。','凡《南次二經》之首，自柜山至于漆吳之山，凡十七山，七千二百里。其神狀皆龍身而鳥首。其祠：毛用一璧瘞，糈用稌。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','5cabed5217f82d26a7bcfef42982144ec4a06af256cf25064815dc185eeec381','published'),
('13000000-0000-4000-8000-000000000029','12000000-0000-4000-8000-000000000003','tianyu','南山经·天虞之山',1,'《南次三經》之首，曰天虞之山，其下多水，不可以上。','《南次三經》之首，曰天虞之山，其下多水，不可以上。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','6b3fa89daf39840c8c41e5d58c74bf33e1d38621799cbfd15b00d9194b83bc38','published'),
('13000000-0000-4000-8000-000000000030','12000000-0000-4000-8000-000000000003','daoguo','南山经·祷过之山',2,'東五百里，曰禱過之山，其上多金玉，其下多犀、兕，多象。有鳥焉，其狀如鵁，而白首、三足、人面，其名曰瞿如，其鳴自號也。泿水出焉，而南流注于海。其中有虎蛟，其狀魚身而蛇尾，其音如鴛鴦，食者不腫，可以已痔。','東五百里，曰禱過之山，其上多金玉，其下多犀、兕，多象。有鳥焉，其狀如鵁，而白首、三足、人面，其名曰瞿如，其鳴自號也。泿水出焉，而南流注于海。其中有虎蛟，其狀魚身而蛇尾，其音如鴛鴦，食者不腫，可以已痔。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','09b24a037e52fed2fa199c406884286c04eb68f4df65ae6df66f306419dbfb27','published'),
('13000000-0000-4000-8000-000000000031','12000000-0000-4000-8000-000000000003','danxue','南山经·丹穴之山',3,'又東五百里，曰丹穴之山，其上多金玉。丹水出焉，而南流注于渤海。有鳥焉，其狀如雞，五采而文，名曰鳳皇，首文曰德，翼文曰義，背文曰禮，膺文曰仁，腹文曰信。是鳥也，飲食自然，自歌自舞，見則天下安寧。','又東五百里，曰丹穴之山，其上多金玉。丹水出焉，而南流注于渤海。有鳥焉，其狀如雞，五采而文，名曰鳳皇，首文曰德，翼文曰義，背文曰禮，膺文曰仁，腹文曰信。是鳥也，飲食自然，自歌自舞，見則天下安寧。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','52e572d3a3ace9e6f4b2ba7639cd0e466ca88be526c5d12e3f9e1aabddab8469','published'),
('13000000-0000-4000-8000-000000000032','12000000-0000-4000-8000-000000000003','fashuang','南山经·发爽之山',4,'又東五百里，曰發爽之山，無草木，多水，多白猿。汎水出焉，而南流注于渤海。','又東五百里，曰發爽之山，無草木，多水，多白猿。汎水出焉，而南流注于渤海。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','9e1a1ea36e14bb20d46b8dba6e2d36d1d58e711b36e0d6a0e5017aa718ec329e','published'),
('13000000-0000-4000-8000-000000000033','12000000-0000-4000-8000-000000000003','maoshan','南山经·旄山',5,'又東四百里，至于旄山之尾，其南有谷，曰育遺，多怪鳥，凱風自是出。','又東四百里，至于旄山之尾，其南有谷，曰育遺，多怪鳥，凱風自是出。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','aba3a9c7fe51a0ea176bd31346ced733e4d8e1563aa82f77d29401ab5237b6e4','published'),
('13000000-0000-4000-8000-000000000034','12000000-0000-4000-8000-000000000003','feishan','南山经·非山',6,'又東四百里，至于非山之首，其上多金玉，無水，其下多蝮虫。','又東四百里，至于非山之首，其上多金玉，無水，其下多蝮虫。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','6681269417f04b9bef220016b4a17b0984f1202b7230c0434cfa660278311ad3','published'),
('13000000-0000-4000-8000-000000000035','12000000-0000-4000-8000-000000000003','yangjia','南山经·阳夹之山',7,'又東五百里，曰陽夾之山，無草木，多水。','又東五百里，曰陽夾之山，無草木，多水。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','d787e4367cd680d8b41ed1bb95937dcf5d8f15e384fae6dba787ba28c1b6bb07','published'),
('13000000-0000-4000-8000-000000000036','12000000-0000-4000-8000-000000000003','guanxiang','南山经·灌湘之山',8,'又東五百里，曰灌湘之山，上多木，無草；多怪鳥，無獸。','又東五百里，曰灌湘之山，上多木，無草；多怪鳥，無獸。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','b6c553259b97cac72feb8d08b197faee1ae76799c80bbcd019ba4f01d2c18a40','published'),
('13000000-0000-4000-8000-000000000037','12000000-0000-4000-8000-000000000003','jishan-3','南山经·鸡山',9,'又東五百里，曰鷄山，其上多金，其下多丹雘。黑水出焉，而南流注于海。其中有鱄魚，其狀如鮒而彘毛，其音如豚，見則天下大旱。','又東五百里，曰鷄山，其上多金，其下多丹雘。黑水出焉，而南流注于海。其中有鱄魚，其狀如鮒而彘毛，其音如豚，見則天下大旱。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','4b0f9a0644e162aaa604ba04d9d2433e560c0da520a5801cb6d164b36512019c','published'),
('13000000-0000-4000-8000-000000000038','12000000-0000-4000-8000-000000000003','lingqiu','南山经·令丘之山',10,'又東四百里，曰令丘之山，無草木，多火。其南有谷焉，曰中谷，條風自是出。有鳥焉，其狀如梟，人面四目而有耳，其名曰顒，其鳴自號也，見則天下大旱。','又東四百里，曰令丘之山，無草木，多火。其南有谷焉，曰中谷，條風自是出。有鳥焉，其狀如梟，人面四目而有耳，其名曰顒，其鳴自號也，見則天下大旱。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','6578c3aa251294ee270f504c9ea2290b2a4377bdde6a581d3693f457be0344ac','published'),
('13000000-0000-4000-8000-000000000039','12000000-0000-4000-8000-000000000003','lunzhe','南山经·仑者之山',11,'又東三百七十里，曰侖者之山，其上多金玉，其下多青䨼。有木焉，其狀如穀而赤理，其汗如漆，其味如飴，食者不飢，可以釋勞，其名曰白䓘，可以血玉。','又東三百七十里，曰侖者之山，其上多金玉，其下多青䨼。有木焉，其狀如穀而赤理，其汗如漆，其味如飴，食者不飢，可以釋勞，其名曰白䓘，可以血玉。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','86478750e60c97c4f75cda89d2f351f0384a2bc6ba9ae7a0723f67f99d96a4be','published'),
('13000000-0000-4000-8000-000000000040','12000000-0000-4000-8000-000000000003','yugao','南山经·禺槀之山',12,'又東五百八十里，曰禺槀之山，多怪獸，多大蛇。','又東五百八十里，曰禺槀之山，多怪獸，多大蛇。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','e3c13418cdc3b81e5377ead938fc01fe30e69267c71746a9fbb06a48719af09f','published'),
('13000000-0000-4000-8000-000000000041','12000000-0000-4000-8000-000000000003','nanyu','南山经·南禺之山',13,'東五百八十里，曰南禺之山，其上多金玉，其下多水。有穴焉，水春輒入，夏乃出，冬則閉。佐水出焉，而東南流注于海，有鳳皇、鵷鶵。','東五百八十里，曰南禺之山，其上多金玉，其下多水。有穴焉，水春輒入，夏乃出，冬則閉。佐水出焉，而東南流注于海，有鳳皇、鵷鶵。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','a1475813bcaef087a26412bbe388b55ea39240b135cfcfb8238992e7896f33d8','published'),
('13000000-0000-4000-8000-000000000042','12000000-0000-4000-8000-000000000003','nanci3-summary','南山经·南次三经·祠礼',14,'凡《南次三經》之首，自天虞之山以至南禺之山，凡一十四山，六千五百三十里。其神皆龍身而人面。其祠皆一白狗祈，糈用稌。','凡《南次三經》之首，自天虞之山以至南禺之山，凡一十四山，六千五百三十里。其神皆龍身而人面。其祠皆一白狗祈，糈用稌。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','e8ba56d8abb484669fef04df66f64d247731af9776b55507337dd484603c4436','published'),
('13000000-0000-4000-8000-000000000043','12000000-0000-4000-8000-000000000003','nanshan-colophon','南山经·结语',15,'右南經之山志，大小凡四十山，萬六千三百八十里。','右南經之山志，大小凡四十山，萬六千三百八十里。','https://ctext.org/shan-hai-jing/nan-shan-jing/zh','3e77f47e2df83e65b7c2651140dece8a8dd038abfe32e9fab2d6e9fdd78ee1eb','published')
INSERT INTO shj_passage_translations(passage_id,locale,title,summary,editorial_note,status) VALUES
('13000000-0000-4000-8000-000000000001','zh-CN','招摇之山','鹊山首列起点，临于西海；祝馀、迷谷与狌狌在此。','V2 起改用全段落切分（nanshan-full-v2）。','published'),
('13000000-0000-4000-8000-000000000001','en','Mount Zhaoyao','The opening mountain of the Queshan route, overlooking the Western Sea; the Zhuyu herb, Migu tree, and Xingxing appear here.','','published'),
('13000000-0000-4000-8000-000000000002','zh-CN','堂庭之山','招摇之山东三百里的山。','','published'),
('13000000-0000-4000-8000-000000000002','en','Mount Tangting','A mountain three hundred li east of Zhaoyao.','','published'),
('13000000-0000-4000-8000-000000000003','zh-CN','猨翼之山','堂庭之山东三百八十里的险峻山地。','','published'),
('13000000-0000-4000-8000-000000000003','en','Mount Yuanyi','A difficult mountain three hundred and eighty li east of Tangting.','','published'),
('13000000-0000-4000-8000-000000000004','zh-CN','杻阳之山','鹿蜀、旋龟与怪水所在的山。','','published'),
('13000000-0000-4000-8000-000000000004','en','Mount Niuyang','The mountain associated with the Lushu, Xuangui, and Guai River.','','published'),
('13000000-0000-4000-8000-000000000005','zh-CN','柢山','多水无草木，鯥所在。','','published'),
('13000000-0000-4000-8000-000000000005','en','Mount Di','A watery, treeless mountain associated with the Lu.','','published'),
('13000000-0000-4000-8000-000000000006','zh-CN','亶爰之山','多水无草木且不可上，类所在。','','published'),
('13000000-0000-4000-8000-000000000006','en','Mount Danyuan','A watery, treeless, unscalable mountain associated with the Lei.','','published'),
('13000000-0000-4000-8000-000000000007','zh-CN','基山','阳面多玉，阴面多怪木；猼訑与三首之鸟𪁺𩿧所在。','','published'),
('13000000-0000-4000-8000-000000000007','en','Mount Ji','A mountain of jade and strange trees, associated with the Boyi and the three-headed Changfu bird.','','published'),
('13000000-0000-4000-8000-000000000008','zh-CN','青丘之山','九尾狐、灌灌、赤鱬及英水所在。','','published'),
('13000000-0000-4000-8000-000000000008','en','Mount Qingqiu','A mountain associated with the Nine-tailed Fox, Guanguan, Chiru, and Ying River.','','published'),
('13000000-0000-4000-8000-000000000009','zh-CN','箕尾之山','鹊山首列东端，山尾抵近东海。','','published'),
('13000000-0000-4000-8000-000000000009','en','Mount Jiwei','The eastern end of the first Queshan route, reaching the Eastern Sea.','','published'),
('13000000-0000-4000-8000-000000000010','zh-CN','鹊山首列·祠礼','首列收束：凡十山、二千九百五十里；其神鸟身龙首，祠用璋玉与稌米。','原文称凡十山而列名九山，差异登记为异文。','published'),
('13000000-0000-4000-8000-000000000010','en','Queshan route rites','Route closing: ten mountains over 2,950 li; bird-bodied, dragon-headed spirits with zhang-jade and glutinous rice rites.','','published'),
('13000000-0000-4000-8000-000000000011','zh-CN','柜山','南次二经起点，西临流黄；英水西南流注赤水；狸力与鴸在此。','','published'),
('13000000-0000-4000-8000-000000000011','en','Mount Ju','The opening mountain of the second route; the Ying River flows southwest to the Red River, and the Lili and Zhu appear here.','','published'),
('13000000-0000-4000-8000-000000000012','zh-CN','长右之山','无草木多水；同名之兽长右在此。','','published'),
('13000000-0000-4000-8000-000000000012','en','Mount Changyou','A treeless, watery mountain sharing its name with the four-eared Changyou.','','published'),
('13000000-0000-4000-8000-000000000013','zh-CN','尧光之山','猾褢穴居冬蛰之山。','','published'),
('13000000-0000-4000-8000-000000000013','en','Mount Yaoguang','The mountain where the burrowing, hibernating Huahuai lives.','','published'),
('13000000-0000-4000-8000-000000000014','zh-CN','羽山','下多水，上多雨，多蝮虫。','','published'),
('13000000-0000-4000-8000-000000000014','en','Mount Yu','A rain-soaked mountain with many fuchong vipers.','','published'),
('13000000-0000-4000-8000-000000000015','zh-CN','瞿父之山','无草木，多金玉。','','published'),
('13000000-0000-4000-8000-000000000015','en','Mount Qufu','A bare mountain rich in metal and jade.','','published'),
('13000000-0000-4000-8000-000000000016','zh-CN','句馀之山','无草木，多金玉。','','published'),
('13000000-0000-4000-8000-000000000016','en','Mount Juyu','A bare mountain rich in metal and jade.','','published'),
('13000000-0000-4000-8000-000000000017','zh-CN','浮玉之山','北望具区；食人之彘所在；苕水出其阴。','','published'),
('13000000-0000-4000-8000-000000000017','en','Mount Fuyu','Overlooking Juqu to the north; home of the man-eating Zhi, with the Tiao River rising on its shaded side.','','published'),
('13000000-0000-4000-8000-000000000018','zh-CN','成山','四方而三坛；𨴯水南流注于虖勺。','','published'),
('13000000-0000-4000-8000-000000000018','en','Mount Cheng','Square with three terraces; its river flows south to Hushao.','','published'),
('13000000-0000-4000-8000-000000000019','zh-CN','会稽之山','四方之山，勺水南流注于湨。','','published'),
('13000000-0000-4000-8000-000000000019','en','Mount Kuaiji','A square mountain whose Shao River flows south to the Ju.','','published'),
('13000000-0000-4000-8000-000000000020','zh-CN','夷山','多沙石；湨水南流注于列涂。','','published'),
('13000000-0000-4000-8000-000000000020','en','Mount Yi','A sandy mountain; the Ju River flows south to Lietu.','','published'),
('13000000-0000-4000-8000-000000000021','zh-CN','仆勾之山','上多金玉，下多草木；无鸟兽，无水。','','published'),
('13000000-0000-4000-8000-000000000021','en','Mount Pugou','Metal and jade above, plants below; no birds, beasts, or water.','','published'),
('13000000-0000-4000-8000-000000000022','zh-CN','咸阴之山','无草木，无水。','','published'),
('13000000-0000-4000-8000-000000000022','en','Mount Xianyin','A bare, waterless mountain.','','published'),
('13000000-0000-4000-8000-000000000023','zh-CN','洵山','无口之兽䍺所在；洵水南流注于阏泽。','','published'),
('13000000-0000-4000-8000-000000000023','en','Mount Xun','Home of the mouthless Huan; the Xun River flows south to the E Marsh.','','published'),
('13000000-0000-4000-8000-000000000024','zh-CN','虖勺之山','上多梓柟，下多荆杞；滂水东流注于海。','','published'),
('13000000-0000-4000-8000-000000000024','en','Mount Hushao','Catalpa and nanmu above, brambles below; the Pang River flows east to the sea.','','published'),
('13000000-0000-4000-8000-000000000025','zh-CN','区吴之山','多砂石；鹿水南流注于滂水。','','published'),
('13000000-0000-4000-8000-000000000025','en','Mount Quwu','A gravelly mountain; the Lu River flows south into the Pang.','','published'),
('13000000-0000-4000-8000-000000000026','zh-CN','鹿吴之山','泽更之水所出；水中之兽蛊雕食人。','','published'),
('13000000-0000-4000-8000-000000000026','en','Mount Luwu','Source of the Zegeng waters, where the horned, man-eating Gudiao dwells.','','published'),
('13000000-0000-4000-8000-000000000027','zh-CN','漆吴之山','处于海滨，望丘山，其光载出载入。','','published'),
('13000000-0000-4000-8000-000000000027','en','Mount Qiwu','A coastal mountain facing Qiushan, where the light rises and sets.','','published'),
('13000000-0000-4000-8000-000000000028','zh-CN','南次二经·祠礼','南次二经收束：凡十七山、七千二百里；其神龙身鸟首，祠毛用一璧瘗。','','published'),
('13000000-0000-4000-8000-000000000028','en','Second route rites','Second route closing: seventeen mountains over 7,200 li; dragon-bodied, bird-headed spirits with a buried bi-disc rite.','','published'),
('13000000-0000-4000-8000-000000000029','zh-CN','天虞之山','南次三经起点，下多水，不可以上。','','published'),
('13000000-0000-4000-8000-000000000029','en','Mount Tianyu','The opening mountain of the third route; watery below and unscalable.','','published'),
('13000000-0000-4000-8000-000000000030','zh-CN','祷过之山','多犀兕象；瞿如与虎蛟所在；泿水南流注于海。','','published'),
('13000000-0000-4000-8000-000000000030','en','Mount Daoguo','Rich in rhinoceros and elephant; home of the Quru and Hujiao, with the Yin River flowing south to the sea.','','published'),
('13000000-0000-4000-8000-000000000031','zh-CN','丹穴之山','凤皇所在；丹水南流注于渤海。','','published'),
('13000000-0000-4000-8000-000000000031','en','Mount Danxue','The mountain of the Fenghuang; the Dan River flows south to the Bo Sea.','','published'),
('13000000-0000-4000-8000-000000000032','zh-CN','发爽之山','无草木，多水，多白猿。','','published'),
('13000000-0000-4000-8000-000000000032','en','Mount Fashuang','A bare, watery mountain with many white apes.','','published'),
('13000000-0000-4000-8000-000000000033','zh-CN','旄山','其尾有育遗之谷，凯风自是出。','','published'),
('13000000-0000-4000-8000-000000000033','en','Mount Mao','Its tail holds the Yuyi valley, from which the south wind rises.','','published'),
('13000000-0000-4000-8000-000000000034','zh-CN','非山','其首多金玉，无水，下多蝮虫。','','published'),
('13000000-0000-4000-8000-000000000034','en','Mount Fei','Metal and jade at its head, no water, and many fuchong vipers below.','','published'),
('13000000-0000-4000-8000-000000000035','zh-CN','阳夹之山','无草木，多水。','','published'),
('13000000-0000-4000-8000-000000000035','en','Mount Yangjia','A bare, watery mountain.','','published'),
('13000000-0000-4000-8000-000000000036','zh-CN','灌湘之山','上多木无草，多怪鸟，无兽。','','published'),
('13000000-0000-4000-8000-000000000036','en','Mount Guanxiang','Wooded but grassless, with many strange birds and no beasts.','','published'),
('13000000-0000-4000-8000-000000000037','zh-CN','鸡山','黑水所出；鱄鱼见则天下大旱。','','published'),
('13000000-0000-4000-8000-000000000037','en','Mount Ji (third route)','Source of the Black River; the Zhuanyu portends great drought.','','published'),
('13000000-0000-4000-8000-000000000038','zh-CN','令丘之山','无草木多火；中谷条风所出；颙所在。','','published'),
('13000000-0000-4000-8000-000000000038','en','Mount Lingqiu','A fiery, bare mountain whose Zhong valley releases the northeast wind; home of the Yong.','','published'),
('13000000-0000-4000-8000-000000000039','zh-CN','仑者之山','有白䓘之木，其汗如漆，可以血玉。','','published'),
('13000000-0000-4000-8000-000000000039','en','Mount Lunzhe','Bears the Baigao tree, whose lacquer-like sap can stain jade.','','published'),
('13000000-0000-4000-8000-000000000040','zh-CN','禺槀之山','多怪兽，多大蛇。','','published'),
('13000000-0000-4000-8000-000000000040','en','Mount Yugao','A mountain of strange beasts and great serpents.','','published'),
('13000000-0000-4000-8000-000000000041','zh-CN','南禺之山','有穴春入夏出；佐水东南流注于海；凤皇、鹓鶵所居。','','published'),
('13000000-0000-4000-8000-000000000041','en','Mount Nanyu','Holds a seasonal cave and the Zuo River; the Fenghuang and Yuanchu dwell here.','','published'),
('13000000-0000-4000-8000-000000000042','zh-CN','南次三经·祠礼','南次三经收束：凡一十四山、六千五百三十里；其神龙身人面，祠皆一白狗祈。','原文称凡一十四山而列名十三山，差异登记为异文。','published'),
('13000000-0000-4000-8000-000000000042','en','Third route rites','Third route closing: fourteen mountains over 6,530 li; dragon-bodied, human-faced spirits with a white-dog rite.','','published'),
('13000000-0000-4000-8000-000000000043','zh-CN','南山经·结语','南经之山志结语：大小凡四十山，万六千三百八十里。','','published'),
('13000000-0000-4000-8000-000000000043','en','Nanshan Jing colophon','The colophon of the southern mountains: forty mountains in all, over 16,380 li.','','published')
