INSERT INTO shj_textual_place_translations(place_id,locale,name,aliases,summary,status) VALUES
('15000000-0000-4000-8000-000000000001','zh-CN','招摇之山',ARRAY['招摇山'],'鹊山首列起点，临于西海；祝馀、迷谷与狌狌在此。','published'),
('15000000-0000-4000-8000-000000000001','en','Mount Zhaoyao',ARRAY[]::text[],'The opening mountain of the Queshan route, overlooking the Western Sea; the Zhuyu herb, Migu tree, and Xingxing appear here.','published'),
('15000000-0000-4000-8000-000000000002','zh-CN','堂庭之山',ARRAY['堂庭山'],'招摇之山东三百里的山。','published'),
('15000000-0000-4000-8000-000000000002','en','Mount Tangting',ARRAY[]::text[],'A mountain three hundred li east of Zhaoyao.','published'),
('15000000-0000-4000-8000-000000000003','zh-CN','猨翼之山',ARRAY['猿翼山'],'堂庭之山东三百八十里的险峻山地。','published'),
('15000000-0000-4000-8000-000000000003','en','Mount Yuanyi',ARRAY[]::text[],'A difficult mountain three hundred and eighty li east of Tangting.','published'),
('15000000-0000-4000-8000-000000000004','zh-CN','杻阳之山',ARRAY['杻阳山'],'鹿蜀、旋龟与怪水所在的山。','published'),
('15000000-0000-4000-8000-000000000004','en','Mount Niuyang',ARRAY[]::text[],'The mountain associated with the Lushu, Xuangui, and Guai River.','published'),
('15000000-0000-4000-8000-000000000005','zh-CN','柢山',ARRAY[]::text[],'多水无草木，鯥所在。','published'),
('15000000-0000-4000-8000-000000000005','en','Mount Di',ARRAY[]::text[],'A watery, treeless mountain associated with the Lu.','published'),
('15000000-0000-4000-8000-000000000006','zh-CN','亶爰之山',ARRAY['亶爰山'],'多水无草木且不可上，类所在。','published'),
('15000000-0000-4000-8000-000000000006','en','Mount Danyuan',ARRAY[]::text[],'A watery, treeless, unscalable mountain associated with the Lei.','published'),
('15000000-0000-4000-8000-000000000007','zh-CN','基山',ARRAY[]::text[],'阳面多玉，阴面多怪木；猼訑与三首之鸟𪁺𩿧所在。','published'),
('15000000-0000-4000-8000-000000000007','en','Mount Ji',ARRAY[]::text[],'A mountain of jade and strange trees, associated with the Boyi and the three-headed Changfu bird.','published'),
('15000000-0000-4000-8000-000000000008','zh-CN','青丘之山',ARRAY['青丘山'],'九尾狐、灌灌、赤鱬及英水所在。','published'),
('15000000-0000-4000-8000-000000000008','en','Mount Qingqiu',ARRAY[]::text[],'A mountain associated with the Nine-tailed Fox, Guanguan, Chiru, and Ying River.','published'),
('15000000-0000-4000-8000-000000000009','zh-CN','箕尾之山',ARRAY['箕尾山'],'鹊山首列东端，山尾抵近东海。','published'),
('15000000-0000-4000-8000-000000000009','en','Mount Jiwei',ARRAY[]::text[],'The eastern end of the first Queshan route, reaching the Eastern Sea.','published'),
('15000000-0000-4000-8000-000000000010','zh-CN','柜山',ARRAY[]::text[],'南次二经起点，西临流黄；英水西南流注赤水；狸力与鴸在此。','published'),
('15000000-0000-4000-8000-000000000010','en','Mount Ju',ARRAY[]::text[],'The opening mountain of the second route; the Ying River flows southwest to the Red River, and the Lili and Zhu appear here.','published'),
('15000000-0000-4000-8000-000000000011','zh-CN','长右之山',ARRAY['长右山'],'无草木多水；同名之兽长右在此。','published'),
('15000000-0000-4000-8000-000000000011','en','Mount Changyou',ARRAY[]::text[],'A treeless, watery mountain sharing its name with the four-eared Changyou.','published'),
('15000000-0000-4000-8000-000000000012','zh-CN','尧光之山',ARRAY['尧光山'],'猾褢穴居冬蛰之山。','published'),
('15000000-0000-4000-8000-000000000012','en','Mount Yaoguang',ARRAY[]::text[],'The mountain where the burrowing, hibernating Huahuai lives.','published'),
('15000000-0000-4000-8000-000000000013','zh-CN','羽山',ARRAY[]::text[],'下多水，上多雨，多蝮虫。','published'),
('15000000-0000-4000-8000-000000000013','en','Mount Yu',ARRAY[]::text[],'A rain-soaked mountain with many fuchong vipers.','published'),
('15000000-0000-4000-8000-000000000014','zh-CN','瞿父之山',ARRAY['瞿父山'],'无草木，多金玉。','published'),
('15000000-0000-4000-8000-000000000014','en','Mount Qufu',ARRAY[]::text[],'A bare mountain rich in metal and jade.','published'),
('15000000-0000-4000-8000-000000000015','zh-CN','句馀之山',ARRAY['句馀山'],'无草木，多金玉。','published'),
('15000000-0000-4000-8000-000000000015','en','Mount Juyu',ARRAY[]::text[],'A bare mountain rich in metal and jade.','published'),
('15000000-0000-4000-8000-000000000016','zh-CN','浮玉之山',ARRAY['浮玉山'],'北望具区；食人之彘所在；苕水出其阴。','published'),
('15000000-0000-4000-8000-000000000016','en','Mount Fuyu',ARRAY[]::text[],'Overlooking Juqu to the north; home of the man-eating Zhi, with the Tiao River rising on its shaded side.','published'),
('15000000-0000-4000-8000-000000000017','zh-CN','成山',ARRAY[]::text[],'四方而三坛；𨴯水南流注于虖勺。','published'),
('15000000-0000-4000-8000-000000000017','en','Mount Cheng',ARRAY[]::text[],'Square with three terraces; its river flows south to Hushao.','published'),
('15000000-0000-4000-8000-000000000018','zh-CN','会稽之山',ARRAY['会稽山'],'四方之山，勺水南流注于湨。','published'),
('15000000-0000-4000-8000-000000000018','en','Mount Kuaiji',ARRAY[]::text[],'A square mountain whose Shao River flows south to the Ju.','published'),
('15000000-0000-4000-8000-000000000019','zh-CN','夷山',ARRAY[]::text[],'多沙石；湨水南流注于列涂。','published'),
('15000000-0000-4000-8000-000000000019','en','Mount Yi',ARRAY[]::text[],'A sandy mountain; the Ju River flows south to Lietu.','published'),
('15000000-0000-4000-8000-000000000020','zh-CN','仆勾之山',ARRAY['仆勾山'],'上多金玉，下多草木；无鸟兽，无水。','published'),
('15000000-0000-4000-8000-000000000020','en','Mount Pugou',ARRAY[]::text[],'Metal and jade above, plants below; no birds, beasts, or water.','published'),
('15000000-0000-4000-8000-000000000021','zh-CN','咸阴之山',ARRAY['咸阴山'],'无草木，无水。','published'),
('15000000-0000-4000-8000-000000000021','en','Mount Xianyin',ARRAY[]::text[],'A bare, waterless mountain.','published'),
('15000000-0000-4000-8000-000000000022','zh-CN','洵山',ARRAY[]::text[],'无口之兽䍺所在；洵水南流注于阏泽。','published'),
('15000000-0000-4000-8000-000000000022','en','Mount Xun',ARRAY[]::text[],'Home of the mouthless Huan; the Xun River flows south to the E Marsh.','published'),
('15000000-0000-4000-8000-000000000023','zh-CN','虖勺之山',ARRAY['虖勺山'],'上多梓柟，下多荆杞；滂水东流注于海。','published'),
('15000000-0000-4000-8000-000000000023','en','Mount Hushao',ARRAY[]::text[],'Catalpa and nanmu above, brambles below; the Pang River flows east to the sea.','published'),
('15000000-0000-4000-8000-000000000024','zh-CN','区吴之山',ARRAY['区吴山'],'多砂石；鹿水南流注于滂水。','published'),
('15000000-0000-4000-8000-000000000024','en','Mount Quwu',ARRAY[]::text[],'A gravelly mountain; the Lu River flows south into the Pang.','published'),
('15000000-0000-4000-8000-000000000025','zh-CN','鹿吴之山',ARRAY['鹿吴山'],'泽更之水所出；水中之兽蛊雕食人。','published'),
('15000000-0000-4000-8000-000000000025','en','Mount Luwu',ARRAY[]::text[],'Source of the Zegeng waters, where the horned, man-eating Gudiao dwells.','published'),
('15000000-0000-4000-8000-000000000026','zh-CN','漆吴之山',ARRAY['漆吴山'],'处于海滨，望丘山，其光载出载入。','published'),
('15000000-0000-4000-8000-000000000026','en','Mount Qiwu',ARRAY[]::text[],'A coastal mountain facing Qiushan, where the light rises and sets.','published'),
('15000000-0000-4000-8000-000000000027','zh-CN','天虞之山',ARRAY['天虞山'],'南次三经起点，下多水，不可以上。','published'),
('15000000-0000-4000-8000-000000000027','en','Mount Tianyu',ARRAY[]::text[],'The opening mountain of the third route; watery below and unscalable.','published'),
('15000000-0000-4000-8000-000000000028','zh-CN','祷过之山',ARRAY['祷过山'],'多犀兕象；瞿如与虎蛟所在；泿水南流注于海。','published'),
('15000000-0000-4000-8000-000000000028','en','Mount Daoguo',ARRAY[]::text[],'Rich in rhinoceros and elephant; home of the Quru and Hujiao, with the Yin River flowing south to the sea.','published'),
('15000000-0000-4000-8000-000000000029','zh-CN','丹穴之山',ARRAY['丹穴山'],'凤皇所在；丹水南流注于渤海。','published'),
('15000000-0000-4000-8000-000000000029','en','Mount Danxue',ARRAY[]::text[],'The mountain of the Fenghuang; the Dan River flows south to the Bo Sea.','published'),
('15000000-0000-4000-8000-000000000030','zh-CN','发爽之山',ARRAY['发爽山'],'无草木，多水，多白猿。','published'),
('15000000-0000-4000-8000-000000000030','en','Mount Fashuang',ARRAY[]::text[],'A bare, watery mountain with many white apes.','published'),
('15000000-0000-4000-8000-000000000031','zh-CN','旄山',ARRAY['旄山之尾'],'其尾有育遗之谷，凯风自是出。','published'),
('15000000-0000-4000-8000-000000000031','en','Mount Mao',ARRAY[]::text[],'Its tail holds the Yuyi valley, from which the south wind rises.','published'),
('15000000-0000-4000-8000-000000000032','zh-CN','非山',ARRAY['非山之首'],'其首多金玉，无水，下多蝮虫。','published'),
('15000000-0000-4000-8000-000000000032','en','Mount Fei',ARRAY[]::text[],'Metal and jade at its head, no water, and many fuchong vipers below.','published'),
('15000000-0000-4000-8000-000000000033','zh-CN','阳夹之山',ARRAY['阳夹山'],'无草木，多水。','published'),
('15000000-0000-4000-8000-000000000033','en','Mount Yangjia',ARRAY[]::text[],'A bare, watery mountain.','published'),
('15000000-0000-4000-8000-000000000034','zh-CN','灌湘之山',ARRAY['灌湘山'],'上多木无草，多怪鸟，无兽。','published'),
