('15000000-0000-4000-8000-000000000035','en','Mount Ji (third route)',ARRAY[]::text[],'Source of the Black River; the Zhuanyu portends great drought.','published'),
('15000000-0000-4000-8000-000000000036','zh-CN','令丘之山',ARRAY['令丘山'],'无草木多火；中谷条风所出；颙所在。','published'),
('15000000-0000-4000-8000-000000000036','en','Mount Lingqiu',ARRAY[]::text[],'A fiery, bare mountain whose Zhong valley releases the northeast wind; home of the Yong.','published'),
