INSERT INTO shj_creature_translations(creature_id,locale,name,aliases,summary,detail,status) VALUES
('14000000-0000-4000-8000-000000000010','zh-CN','𪁺𩿧',ARRAY[]::text[],'鸡形而三首六目、六足三翼之鸟。','食之无卧作为原文效应记录，不作现代功效声明。','published'),
('14000000-0000-4000-8000-000000000010','en','Changfu',ARRAY['𪁺𩿧'],'A chicken-like bird with three heads, six eyes, six legs, and three wings.','Its sleep-banishing effect is preserved as an ancient claim, not modern advice.','published'),
('14000000-0000-4000-8000-000000000011','zh-CN','狸力',ARRAY[]::text[],'豚形有距之兽，声音如狗吠。','见则其县多土功，属原文征兆记载。','published'),
('14000000-0000-4000-8000-000000000011','en','Lili',ARRAY['狸力'],'A piglet-shaped beast with spurs and a bark-like call.','Its appearance portending earthworks is a textual omen claim.','published'),
('14000000-0000-4000-8000-000000000012','zh-CN','鴸',ARRAY['鴸鸟'],'鸱形而人手之鸟，鸣声即其名。','见则其县多放士，属原文征兆记载。','published'),
('14000000-0000-4000-8000-000000000012','en','Zhu',ARRAY['鴸'],'An owl-like bird with human hands whose cry speaks its own name.','Its appearance portending banished scholars is a textual omen claim.','published'),
('14000000-0000-4000-8000-000000000013','zh-CN','长右',ARRAY[]::text[],'禺形四耳之兽，与所居之山同名。','见则郡县大水，属原文征兆记载；概念与山各自建模。','published'),
('14000000-0000-4000-8000-000000000013','en','Changyou',ARRAY['长右'],'A four-eared, ape-like beast sharing its mountain''s name.','Its flood omen is textual; the beast and the mountain are modelled separately.','published'),
('14000000-0000-4000-8000-000000000014','zh-CN','猾褢',ARRAY[]::text[],'人形彘鬣之兽，穴居冬蛰，声音如斲木。','见则县有大繇，属原文征兆记载。','published'),
('14000000-0000-4000-8000-000000000014','en','Huahuai',ARRAY['猾褢'],'A humanoid beast with boar bristles that burrows and hibernates, sounding like chopped wood.','Its corvee omen is preserved as a textual claim.','published'),
('14000000-0000-4000-8000-000000000015','zh-CN','彘',ARRAY[]::text[],'虎形牛尾之兽，声音如吠犬，食人。','是食人按原文记录。','published'),
('14000000-0000-4000-8000-000000000015','en','Zhi',ARRAY['彘'],'A tiger-shaped, ox-tailed beast with a barking call, said to eat people.','The man-eating description is preserved from the text.','published'),
('14000000-0000-4000-8000-000000000016','zh-CN','䍺',ARRAY[]::text[],'羊形而无口之兽，原文称不可杀。','不可杀也按原文记录，不作生物学推演。','published'),
('14000000-0000-4000-8000-000000000016','en','Huan',ARRAY['䍺'],'A sheep-like beast with no mouth, said to be unkillable.','Its unkillable nature is preserved as text, not biology.','published'),
('14000000-0000-4000-8000-000000000017','zh-CN','蛊雕',ARRAY['蠱雕'],'雕形有角之水兽，声音如婴儿，食人。','居泽更之水中，是食人按原文记录。','published'),
('14000000-0000-4000-8000-000000000017','en','Gudiao',ARRAY['蛊雕'],'A horned, eagle-shaped water beast with an infant-like cry, said to eat people.','It dwells in the Zegeng waters; the man-eating description is textual.','published'),
('14000000-0000-4000-8000-000000000018','zh-CN','瞿如',ARRAY[]::text[],'鵁形白首、三足人面之鸟，鸣声即其名。','鸣自号也按原文记录。','published'),
('14000000-0000-4000-8000-000000000018','en','Quru',ARRAY['瞿如'],'A white-headed, three-legged, human-faced bird whose cry speaks its own name.','The self-naming call is preserved from the text.','published'),
('14000000-0000-4000-8000-000000000019','zh-CN','虎蛟',ARRAY[]::text[],'鱼身蛇尾之水兽，声音如鸳鸯。','食者不肿、可以已痔属原文效应记载，不作现代医学声明。','published'),
('14000000-0000-4000-8000-000000000019','en','Hujiao',ARRAY['虎蛟'],'A fish-bodied, serpent-tailed water creature that calls like mandarin ducks.','The healing effects are ancient claims, not modern medicine.','published'),
('14000000-0000-4000-8000-000000000020','zh-CN','凤皇',ARRAY['凤凰','鳳凰'],'五采而文之鸟，纹章分别象德义礼仁信。','饮食自然、自歌自舞、见则天下安宁均按原文记录；以鳳皇为正名，鳳凰为通行后起写法。','published'),
('14000000-0000-4000-8000-000000000020','en','Fenghuang',ARRAY['凤皇'],'A five-coloured bird whose markings spell virtue, duty, ritual, humaneness, and trust.','Its self-sufficiency, song, dance, and peace omen are textual; Fenghuang is the canonical form with 鳳凰 as the later common spelling.','published'),
('14000000-0000-4000-8000-000000000021','zh-CN','鱄鱼',ARRAY['鱄魚'],'鲋形而彘毛之鱼，声音如豚。','见则天下大旱，属原文征兆记载。','published'),
('14000000-0000-4000-8000-000000000021','en','Zhuanyu',ARRAY['鱄鱼'],'A carp-like fish with boar bristles and a pig-like call.','Its drought omen is preserved as a textual claim.','published'),
('14000000-0000-4000-8000-000000000022','zh-CN','颙',ARRAY['顒'],'枭形人面、四目有耳之鸟，鸣声即其名。','见则天下大旱，属原文征兆记载。','published'),
('14000000-0000-4000-8000-000000000022','en','Yong',ARRAY['颙'],'An owl-shaped, human-faced bird with four eyes and ears whose cry speaks its own name.','Its drought omen is preserved as a textual claim.','published'),
('14000000-0000-4000-8000-000000000023','zh-CN','鹓鶵',ARRAY['鵷鶵'],'与凤皇并举的仅名之鸟，原文无形态描述。','仅存名号，无形态记载，概念状态标为待定。','published'),
('14000000-0000-4000-8000-000000000023','en','Yuanchu',ARRAY['鹓鶵'],'A name-only bird listed beside the Fenghuang, with no description in the text.','Only the name survives here, so the concept stays provisional.','published')
INSERT INTO shj_creature_occurrences(id,creature_id,passage_id,place_id,surface_form,quote_zh,occurrence_order,source_attestation,interpretation_class,confidence,evidence_note,review_status) VALUES
('16000000-0000-4000-8000-000000000010','14000000-0000-4000-8000-000000000010','13000000-0000-4000-8000-000000000007','15000000-0000-4000-8000-000000000007','𪁺𩿧','其狀如雞而三首六目，六足三翼，其名曰𪁺𩿧，食之無臥。',2,'text_direct','transcription','high','Named occurrence in the Changfu passage.','published'),
('16000000-0000-4000-8000-000000000011','14000000-0000-4000-8000-000000000011','13000000-0000-4000-8000-000000000011','15000000-0000-4000-8000-000000000010','狸力','其狀如豚，有距，其音如狗吠，其名曰狸力，見則其縣多土功。',1,'text_direct','transcription','high','Named occurrence in the Lili passage.','published'),
('16000000-0000-4000-8000-000000000012','14000000-0000-4000-8000-000000000012','13000000-0000-4000-8000-000000000011','15000000-0000-4000-8000-000000000010','鴸','其狀如鴟而人手，其音如痺，其名曰鴸，其鳴自號也，見則其縣多放士。',2,'text_direct','transcription','high','Named occurrence in the Zhu passage.','published'),
('16000000-0000-4000-8000-000000000013','14000000-0000-4000-8000-000000000013','13000000-0000-4000-8000-000000000012','15000000-0000-4000-8000-000000000011','長右','其狀如禺而四耳，其名長右，其音如吟，見則郡縣大水。',1,'text_direct','transcription','high','Named occurrence in the Changyou passage.','published'),
('16000000-0000-4000-8000-000000000014','14000000-0000-4000-8000-000000000014','13000000-0000-4000-8000-000000000013','15000000-0000-4000-8000-000000000012','猾褢','其狀如人而彘鬣，穴居而冬蟄，其名曰猾褢，其音如斲木，見則縣有大繇。',1,'text_direct','transcription','high','Named occurrence in the Huahuai passage.','published'),
('16000000-0000-4000-8000-000000000015','14000000-0000-4000-8000-000000000015','13000000-0000-4000-8000-000000000017','15000000-0000-4000-8000-000000000016','彘','其狀如虎而牛尾，其音如吠犬，其名曰彘，是食人。',1,'text_direct','transcription','high','Named occurrence in the Zhi passage.','published'),
('16000000-0000-4000-8000-000000000016','14000000-0000-4000-8000-000000000016','13000000-0000-4000-8000-000000000023','15000000-0000-4000-8000-000000000022','䍺','其狀如羊而無口，不可殺也，其名曰䍺。',1,'text_direct','transcription','high','Named occurrence in the Huan passage.','published'),
('16000000-0000-4000-8000-000000000017','14000000-0000-4000-8000-000000000017','13000000-0000-4000-8000-000000000026','15000000-0000-4000-8000-000000000025','蠱雕','名曰蠱雕，其狀如雕而有角，其音如嬰兒之音，是食人。',1,'text_direct','transcription','high','Named occurrence in the Gudiao passage.','published'),
('16000000-0000-4000-8000-000000000018','14000000-0000-4000-8000-000000000018','13000000-0000-4000-8000-000000000030','15000000-0000-4000-8000-000000000028','瞿如','其狀如鵁，而白首、三足、人面，其名曰瞿如，其鳴自號也。',1,'text_direct','transcription','high','Named occurrence in the Quru passage.','published'),
('16000000-0000-4000-8000-000000000019','14000000-0000-4000-8000-000000000019','13000000-0000-4000-8000-000000000030','15000000-0000-4000-8000-000000000028','虎蛟','其中有虎蛟，其狀魚身而蛇尾，其音如鴛鴦，食者不腫，可以已痔。',2,'text_direct','transcription','high','Named occurrence in the Hujiao passage.','published'),
('16000000-0000-4000-8000-000000000020','14000000-0000-4000-8000-000000000020','13000000-0000-4000-8000-000000000031','15000000-0000-4000-8000-000000000029','鳳皇','有鳥焉，其狀如雞，五采而文，名曰鳳皇，首文曰德，翼文曰義，背文曰禮，膺文曰仁，腹文曰信。',1,'text_direct','transcription','high','Named occurrence in the Fenghuang passage.','published'),
('16000000-0000-4000-8000-000000000021','14000000-0000-4000-8000-000000000021','13000000-0000-4000-8000-000000000037','15000000-0000-4000-8000-000000000035','鱄魚','其中有鱄魚，其狀如鮒而彘毛，其音如豚，見則天下大旱。',1,'text_direct','transcription','high','Named occurrence in the Zhuanyu passage.','published'),
('16000000-0000-4000-8000-000000000022','14000000-0000-4000-8000-000000000022','13000000-0000-4000-8000-000000000038','15000000-0000-4000-8000-000000000036','顒','其狀如梟，人面四目而有耳，其名曰顒，其鳴自號也，見則天下大旱。',1,'text_direct','transcription','high','Named occurrence in the Yong passage.','published'),
('16000000-0000-4000-8000-000000000023','14000000-0000-4000-8000-000000000023','13000000-0000-4000-8000-000000000041','15000000-0000-4000-8000-000000000039','鵷鶵','佐水出焉，而東南流注于海，有鳳皇、鵷鶵。',1,'text_direct','transcription','high','Named occurrence in the Yuanchu passage.','published'),
('16000000-0000-4000-8000-000000000024','14000000-0000-4000-8000-000000000020','13000000-0000-4000-8000-000000000041','15000000-0000-4000-8000-000000000039','鳳皇','有鳳皇、鵷鶵。',2,'text_direct','transcription','high','Second textual occurrence of the Fenghuang concept, at Mount Nanyu.','published')
