INSERT INTO shj_passage_audits(passage_id,audit_status,segmentation_version,input_checksum_sha256,reviewer_role,reviewed_at,evidence_note)
INSERT INTO shj_text_variants(id,passage_id,occurrence_candidate_id,variant_form,variant_type,source_note,decision_key,reviewer_role,reviewed_at) VALUES
('1c000000-0000-4000-8000-000000000002','13000000-0000-4000-8000-000000000003',NULL,'腹虫','edition_reading','ctext prints 多腹虫; the collation retains the received reading 蝮虫.','collation-fuchong','R-CLASSICS',DATE '2026-08-18'),
('1c000000-0000-4000-8000-000000000003','13000000-0000-4000-8000-000000000005',NULL,'東三百里祗山','edition_reading','ctext opens the passage 東三百里祗山; wikisource prints 又東三百里柢山. The collation reads 又東三百里，曰柢山.','collation-dishan','R-CLASSICS',DATE '2026-08-18'),
('1c000000-0000-4000-8000-000000000004','13000000-0000-4000-8000-000000000010',NULL,'凡十山','unresolved','The closing counts ten mountains while nine are named in the received route; retained as an unresolved count discrepancy.','queshan-count','R-CLASSICS',DATE '2026-08-18'),
('1c000000-0000-4000-8000-000000000005','13000000-0000-4000-8000-000000000042',NULL,'凡一十四山','unresolved','The closing counts fourteen mountains while thirteen are named in the received route; retained as an unresolved count discrepancy.','nanci3-count','R-CLASSICS',DATE '2026-08-18')
INSERT INTO shj_editorial_decisions(id,work_id,decision_key,decision_type,subject_kind,subject_ref,decision_status,rationale,evidence_note,reviewer_role,decided_at) VALUES
('19000000-0000-4000-8000-000000000111','10000000-0000-4000-8000-000000000011','resegmentation-nanshan-full-v2','variant','passage','nanshan-v1-public-domain-collation','accepted','Upgrade the nine V1 excerpts to full received paragraphs and extend the same segmentation to all three routes, so coverage counts audit whole paragraphs rather than excerpts.','Nine V1 passages re-checksummed; thirty-four passages added; occurrence order inside 青丘 recomputed from the received text.','R-CLASSICS',DATE '2026-08-18'),
('19000000-0000-4000-8000-000000000112','10000000-0000-4000-8000-000000000011','flora-minerals-passage-level','exclusion','occurrence','plants-and-minerals','accepted','Plants, trees, and minerals (祝馀、迷谷、育沛、白䓘 and similar) remain passage-level content in V2; dedicated flora/mineral kinds are deferred to Scale.','They stay searchable through passage text without being forced into the creature model.','R-CLASSICS',DATE '2026-08-18'),
('19000000-0000-4000-8000-000000000113','10000000-0000-4000-8000-000000000011','real-fauna-not-concepts','exclusion','occurrence','xi-si-xiang','accepted','犀、兕、象 at 祷过之山 are real-fauna abundance notes, not anomalous creature concepts, and are not modelled as creatures.','The passage lists them alongside metals as local products.','R-CLASSICS',DATE '2026-08-18'),
('19000000-0000-4000-8000-000000000114','10000000-0000-4000-8000-000000000011','canonical-fenghuang','canonical_name','creature','fenghuang','accepted','Use 鳳皇 as the canonical concept label as printed in the passage, with 鳳凰 recorded as the later common spelling.','Named at 丹穴之山 and mentioned again at 南禺之山.','R-CLASSICS',DATE '2026-08-18'),
('19000000-0000-4000-8000-000000000115','10000000-0000-4000-8000-000000000011','yuanchu-provisional','canonical_name','creature','yuanchu','provisional','鵷鶵 appears as a name beside 鳳皇 with no description, so the concept stays provisional pending commentary review.','Name-only mention at 南禺之山.','R-CLASSICS',DATE '2026-08-18'),
('19000000-0000-4000-8000-000000000116','10000000-0000-4000-8000-000000000011','changyou-name-collision','canonical_name','creature','changyou-beast','accepted','The beast 長右 shares its mountain''s name; concept and place are modelled separately without inventing a distinct beast name.','Named at 長右之山.','R-CLASSICS',DATE '2026-08-18')
